    sc=U@v; i=np.argsort(-sc)[:n]; j=np.argsort(sc)[:n]; return [tok.text(x) for x in i],[tok.text(x) for x in j]
def etoks(v,n=8):
    sc=En@v; i=np.argsort(-sc)[:n]; j=np.argsort(sc)[:n]; return [tok.text(x) for x in i],[tok.text(x) for x in j]
